"""Cart pricing."""

import re

from cart.models import Line, Totals

_COUPON = re.compile(r"(PERCENT|FIXED):([0-9]+)")


def _percent_of(cents: int, percent: int) -> int:
    """`percent` of `cents`, rounded to a whole cent with halves rounding up."""
    return (cents * percent + 50) // 100


def price_cart(lines: list[Line], coupon: str | None = None) -> Totals:
    """Price a cart. See README.md for the discount rules."""
    kind = value = None
    if coupon is not None:
        match = _COUPON.fullmatch(coupon)
        if match is None:
            raise ValueError(f"invalid coupon: {coupon!r}")
        kind, value = match.group(1), int(match.group(2))
        if kind == "PERCENT" and not 1 <= value <= 100:
            raise ValueError(f"percentage out of range: {coupon!r}")

    subtotal = 0
    bulk_discount = 0
    for line in lines:
        if line.qty < 1:
            raise ValueError(f"quantity must be at least 1: {line!r}")
        if line.unit_cents < 0:
            raise ValueError(f"unit price must not be negative: {line!r}")
        amount = line.unit_cents * line.qty
        subtotal += amount
        if line.qty >= 10:
            bulk_discount += _percent_of(amount, 10)

    remaining = subtotal - bulk_discount
    if kind == "PERCENT":
        coupon_discount = _percent_of(remaining, value)
    elif kind == "FIXED":
        coupon_discount = min(value, remaining)
    else:
        coupon_discount = 0

    discount = bulk_discount + coupon_discount
    return Totals(subtotal, discount, subtotal - discount)
